private theorem polynomialGenerator (R : Type u) [CommRing R] (a b : R) :
    polynomialEquivalence R a b (QuadraticAlgebra.omega : QuadraticAlgebra R a b) =
      AdjoinRoot.root (QuadraticAlgebra.definingPolynomial a b)

private theorem numberFieldFromDomain (a b : ℤ)
    [IsDomain (QuadraticAlgebra ℤ a b)] :
    ∃ _ : NumberField (FractionRing (QuadraticAlgebra ℤ a b)), True

private theorem negativeFiveDegreeAndDiscriminant :
    Module.finrank ℚ QuadraticAlgebra.SqrtNegFiveField = 2 ∧
      NumberField.discr QuadraticAlgebra.SqrtNegFiveField = -20

private theorem reductionOnGenerator :
    QuadraticAlgebra.sqrtNegFiveModTwo
      (QuadraticAlgebra.omega : QuadraticAlgebra.SqrtNegFiveOrder) = 1

private theorem complexGenerator :
    QuadraticAlgebra.realComplexEquiv
        (QuadraticAlgebra.omega : QuadraticAlgebra ℝ (-1) 0) = Complex.I

private theorem nonmonicGaussianRoot :
    (C (2 : ℝ) * (X ^ 2 + 1)).aeval
        (QuadraticAlgebra.omega : QuadraticAlgebra ℝ (-1) 0) = 0

private theorem negativeFiveDiscriminantAndClassNumber :
    NumberField.discr QuadraticAlgebra.SqrtNegFiveField = -20 ∧
      NumberField.classNumber QuadraticAlgebra.SqrtNegFiveField = 2

private theorem translatedPolynomial :
    QuadraticAlgebra.definingPolynomial (-2 : ℚ) 2 =
      (X ^ 2 - C (2 : ℚ) * X + C (2 : ℚ) : ℚ[X])

private theorem gaussianQuotientWitness :
    (2 : ℚ) ^ 2 = -(QuadraticAlgebra.discr
      (-(X ^ 2 + 1 : ℚ[X]).coeff 0) (-(X ^ 2 + 1 : ℚ[X]).coeff 1))

private theorem integerCongruenceClosure (f : ℤ)
    (hmod : f % 4 = 2 ∨ f % 4 = 3) (hf : Squarefree f) :
    IsIntegrallyClosed (QuadraticAlgebra ℤ f 0)

private theorem concreteFieldAndClasses :
    Module.finrank ℚ QuadraticAlgebra.SqrtNegFiveField = 2 ∧
      NumberField.classNumber QuadraticAlgebra.SqrtNegFiveField = 2

private theorem definingPolynomialReduction (R : Type u) [CommRing R] (a b : R) :
    QuadraticAlgebra.definingPolynomial a b =
      Polynomial.X ^ 2 - (Polynomial.C b * Polynomial.X + Polynomial.C a)

theorem isDomain_int_of_emod_four {f : ℤ}
    (hmod : f % 4 = 2 ∨ f % 4 = 3) :
    IsDomain (QuadraticAlgebra ℤ f 0)

theorem isIntegral_star [CommRing R] [CommRing K] [Algebra R K]
    {a b : K} {x : QuadraticAlgebra K a b}
    (hx : IsIntegral R x) : IsIntegral R (star x)

@[simp]
theorem map_adjoinRoot_of {R : Type u} {S : Type v} {F : Type w}
    [CommRing R] [Semiring S] [Algebra R S] {p : R[X]}
    [FunLike F (AdjoinRoot p) S] [AlgHomClass F R (AdjoinRoot p) S] (e : F) (r : R) :
    e (AdjoinRoot.of p r) = algebraMap R S r

proof:
:= by
  let _ : IsNoetherianRing (QuadraticAlgebra R a b) :=
    IsNoetherianRing.of_finite R _
  let _ : Ring.DimensionLEOne (QuadraticAlgebra R a b) :=
    Ring.DimensionLEOne.of_isIntegral R _
  let _ : IsDedekindRing (QuadraticAlgebra R a b) := { }
  infer_instance
